def _safe_streetsmart_slug(value):
    if not value:
        sanitized = re.sub('[^A-Za-z0-9._-]+', '_', str('').strip().lower())
    else:
        sanitized = re.sub('[^A-Za-z0-9._-]+', '_', str(value).strip().lower())
    __temp_12 = sanitized.strip('._-')
    if not __temp_12:
        return 'default'
    else:
        return __temp_12

def load_streetsmart_state():
    state_path = streetsmart_state_path()
    payload = json.loads(state_path.read_text(encoding='utf-8'))
    if not isinstance(payload, dict):
        return default_streetsmart_state()
    version = payload.get('version', 0)
    normalized_version = int(version)
    selection = payload.get('selection')
    if selection is not None:
        if not isinstance(selection, dict):
            selection = None
    return {version: normalized_version, selection: selection}

def streetsmart_selection_center(selection):
    if not isinstance(selection, dict):
        return None
    center = selection.get('center')
    if isinstance(center, (list, tuple)):
        if len(center) < 2:
            return None
    else:
        return None
    x = float(center[0])
    y = float(center[1])
    if x == x:
        if not y == y:
            return None
    else:
        return None
    return x, y

def streetsmart_selection_url(selection):
    center = streetsmart_selection_center(selection)
    if center is None:
        return STREETSMART_WEB_URL
    query = format(center[0], '.2f') + ';' + format(center[1], '.2f') + ';' + str(
        STREETSMART_RD_SRS)
    return str(STREETSMART_WEB_URL) + '?q=' + str(quote(query, safe=';:.-'))

def streetsmart_login_script(username, password):
    return """
        (() => {
          const USERNAME = """ + str(json.dumps(username)) + """;
          const PASSWORD = """ + str(json.dumps(password)) + """;
          const AUTO_LOGIN_COUNTER_KEY = 'klic-streetsmart-auto-login-count';
          const NEXT_LABELS = ['volgende', 'next', 'continue', 'doorgaan'];
          const SUBMIT_LABELS = ['inloggen', 'log in', 'login', 'sign in', 'aanmelden'];
          const DASHBOARD_HEIGHT_THRESHOLD = 120;
          const ACTION_DEBOUNCE_MS = 1400;
          const FIELD_SETTLE_MS = 260;
          const MAX_AUTO_LOGIN_ACTIONS = 6;

          const normalizeText = (value) => String(value || '').replace(/\\s+/g, ' ').trim().toLowerCase();

          const isVisible = (element) => {
            if (!(element instanceof HTMLElement)) {
              return false;
            }
            if (element.hidden || element.getAttribute('aria-hidden') === 'true' || element.disabled) {
              return false;
            }
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
          };

          const firstVisible = (selectors) => {
            for (const selector of selectors) {
              const matches = Array.from(document.querySelectorAll(selector));
              for (const element of matches) {
                if (isVisible(element)) {
                  return element;
                }
              }
            }
            return null;
          };

          const setFieldValue = (element, value) => {
            if (!element) {
              return;
            }
            const prototype = element instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
            const descriptor = Object.getOwnPropertyDescriptor(prototype, 'value');
            if (descriptor && typeof descriptor.set === 'function') {
              descriptor.set.call(element, value);
            } else {
              element.value = value;
            }
            element.dispatchEvent(new Event('input', { bubbles: true }));
            element.dispatchEvent(new Event('change', { bubbles: true }));
          };

          const findActionButton = (labels) => {
            const candidates = Array.from(
              document.querySelectorAll('button, input[type="submit"], input[type="button"]')
            );
            for (const candidate of candidates) {
              if (!(candidate instanceof HTMLElement) || !isVisible(candidate)) {
                continue;
              }
              const label = normalizeText(
                candidate.textContent || candidate.value || candidate.getAttribute('aria-label') || ''
              );
              if (labels.some((expected) => label.includes(expected))) {
                return candidate;
              }
            }
            return null;
          };

          const clickElement = (element) => {
            if (!(element instanceof HTMLElement) || !isVisible(element)) {
              return false;
            }
            element.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window }));
            element.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, view: window }));
            element.click();
            return true;
          };

          const submitForm = (form, submitter) => {
            if (!(form instanceof HTMLFormElement)) {
              return false;
            }
            if (typeof form.requestSubmit === 'function') {
              if (submitter instanceof HTMLElement) {
                form.requestSubmit(submitter);
              } else {
                form.requestSubmit();
              }
            } else {
              form.submit();
            }
            return true;
          };

          const navigateSameWindow = (rawUrl) => {
            if (!rawUrl) {
              return window;
            }
            const urlText = String(rawUrl).trim();
            if (!urlText || urlText.startsWith('javascript:') || urlText.startsWith('mailto:') || urlText.startsWith('tel:')) {
              return window;
            }
            try {
              window.location.href = new URL(urlText, window.location.href).href;
            } catch (_error) {
              window.location.href = urlText;
            }
            return window;
          };

          if (!window.__klicStreetSmartBrowserPatched) {
            window.__klicStreetSmartBrowserPatched = true;

            window.open = function(url) {
              return navigateSameWindow(url);
            };

            document.addEventListener('click', (event) => {
              if (event.defaultPrevented || event.button !== 0) {
                return;
              }
              if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
                return;
              }
              const anchor = event.target instanceof Element ? event.target.closest('a[href]') : null;
              if (!anchor || anchor.hasAttribute('download')) {
                return;
              }
              const target = String(anchor.getAttribute('target') || '').trim().toLowerCase();
              if (target !== '_blank' && target !== '_new') {
                return;
              }
              event.preventDefault();
              navigateSameWindow(anchor.href || anchor.getAttribute('href'));
            }, true);
          }

          const collapseDashboard = () => {
            const tabsContainer = document.querySelector('.tabs-container');
            if (!(tabsContainer instanceof HTMLElement) || !isVisible(tabsContainer)) {
              return false;
            }
            const rect = tabsContainer.getBoundingClientRect();
            if (rect.height <= DASHBOARD_HEIGHT_THRESHOLD) {
              return false;
            }
            const now = Date.now();
            const lastClickAt = Number(window.__klicStreetSmartDashboardClickAt || '0');
            if ((now - lastClickAt) < ACTION_DEBOUNCE_MS) {
              return false;
            }
            const collapseButton = firstVisible([
              'button[data-testid="dashboard-collapse-button"]',
              'button.dashboard-expand',
            ]);
            if (collapseButton) {
              window.__klicStreetSmartDashboardClickAt = now;
              return clickElement(collapseButton);
            }
            tabsContainer.style.maxHeight = '0px';
            tabsContainer.style.overflow = 'hidden';
            tabsContainer.style.border = '0';
            tabsContainer.style.padding = '0';
            return true;
          };

          const mosaicWindows = () => Array.from(
            document.querySelectorAll('.mosaic-window.cm-mosaic-window, .mosaic-window')
          ).filter((element) => {
            if (!(element instanceof HTMLElement) || !isVisible(element)) {
              return false;
            }
            const rect = element.getBoundingClientRect();
            return rect.width >= 180 && rect.height >= 140;
          });

          const windowSignature = (windows) => windows
            .map((element) => {
              const rect = element.getBoundingClientRect();
              return `${Math.round(rect.left)}:${Math.round(rect.top)}:${Math.round(rect.width)}:${Math.round(rect.height)}`;
            })
            .join('|');

          const preferredWindow = (windows) => {
            const viewportCenter = window.innerWidth / 2;
            const items = windows.map((element) => {
              const rect = element.getBoundingClientRect();
              const haystack = normalizeText([
                element.className || '',
                element.getAttribute('data-testid') || '',
                element.textContent || '',
                Array.from(element.querySelectorAll('[class],[data-testid]'))
                  .slice(0, 28)
                  .map((node) => [node.className || '', node.getAttribute('data-testid') || ''].join(' '))
                  .join(' '),
              ].join(' '));
              let score = 0;
              if (haystack.includes('panorama')) {
                score += 40;
              }
              if (haystack.includes('cyclorama') || haystack.includes('recording') || haystack.includes('street')) {
                score += 30;
              }
              if (haystack.includes('oblique')) {
                score += 12;
              }
              if (haystack.includes('point cloud')) {
                score += 8;
              }
              if (haystack.includes('viewer-container__map') || haystack.includes('location-map') || haystack.includes('basemap')) {
                score -= 30;
              }
              const centerX = rect.left + (rect.width / 2);
              score -= Math.abs(centerX - viewportCenter) / Math.max(window.innerWidth, 1);
              return {
                element,
                rect,
                centerX,
                score,
              };
            });
            if (!items.length) {
              return null;
            }
            if (items.length >= 3) {
              const middleItem = [...items].sort((left, right) => left.centerX - right.centerX)[Math.floor(items.length / 2)];
              if (middleItem) {
                return middleItem.element;
              }
            }
            items.sort((left, right) => right.score - left.score);
            return items[0].element;
          };

          const maximizePreferredWindow = () => {
            const windows = mosaicWindows();
            if (windows.length < 2) {
              return false;
            }
            const signature = windowSignature(windows);
            if (window.__klicStreetSmartMaximizedSignature === signature) {
              return false;
            }
            const now = Date.now();
            const lastClickAt = Number(window.__klicStreetSmartMaximizeClickAt || '0');
            if ((now - lastClickAt) < ACTION_DEBOUNCE_MS) {
              return false;
            }
            const targetWindow = preferredWindow(windows);
            if (!(targetWindow instanceof HTMLElement)) {
              return false;
            }
            const maximizeButton = Array.from(
              targetWindow.querySelectorAll(
                'button.btn-maximize, button[data-testid^="maxmize-"], button[data-testid^="maximize-"]'
              )
            ).find((element) => isVisible(element));
            if (!(maximizeButton instanceof HTMLElement)) {
              return false;
            }
            window.__klicStreetSmartMaximizeClickAt = now;
            window.__klicStreetSmartMaximizedSignature = signature;
            return clickElement(maximizeButton);
          };

          const applyViewerLayout = () => {
            try {
              collapseDashboard();
            } catch (_error) {
            }
            try {
              maximizePreferredWindow();
            } catch (_error) {
            }
          };

          if (!window.__klicStreetSmartLayoutTimer) {
            window.__klicStreetSmartLayoutTimer = window.setInterval(() => {
              applyViewerLayout();
            }, 1200);
            document.addEventListener('visibilitychange', () => {
              if (!document.hidden) {
                applyViewerLayout();
              }
            }, true);
          }
          window.setTimeout(applyViewerLayout, 120);
          window.setTimeout(applyViewerLayout, 850);
          window.setTimeout(applyViewerLayout, 2400);

          const authState = window.__klicStreetSmartAuthState || (window.__klicStreetSmartAuthState = {
            lastActionAt: 0,
            lastActionKey: '',
            lastFieldFillAt: 0,
            lastFieldStage: '',
          });

          const getAttempts = () => Number(sessionStorage.getItem(AUTO_LOGIN_COUNTER_KEY) || '0');
          const clearAttempts = () => {
            sessionStorage.removeItem(AUTO_LOGIN_COUNTER_KEY);
            authState.lastActionKey = '';
          };
          const bumpAttempts = () => {
            const nextAttempts = getAttempts() + 1;
            sessionStorage.setItem(AUTO_LOGIN_COUNTER_KEY, String(nextAttempts));
            return nextAttempts;
          };
          const canPerformAction = (actionKey) => {
            const now = Date.now();
            if (authState.lastActionKey === actionKey && (now - authState.lastActionAt) < ACTION_DEBOUNCE_MS) {
              return false;
            }
            authState.lastActionAt = now;
            authState.lastActionKey = actionKey;
            return true;
          };
          const noteFieldFill = (stage) => {
            authState.lastFieldStage = stage;
            authState.lastFieldFillAt = Date.now();
          };
          const fieldRecentlyFilled = (stage) => {
            return authState.lastFieldStage === stage && (Date.now() - authState.lastFieldFillAt) < FIELD_SETTLE_MS;
          };
          const syncFieldValue = (element, value, stage) => {
            if (!(element instanceof HTMLInputElement) && !(element instanceof HTMLTextAreaElement)) {
              return false;
            }
            if (String(element.value || '') === String(value || '')) {
              return false;
            }
            element.focus();
            setFieldValue(element, value);
            noteFieldFill(stage);
            return true;
          };

          const loginFields = () => {
            return {
              usernameInput: firstVisible([
                'input[name="username"]',
                'input[name="email"]',
                'input[name="identifier"]',
                'input[name="loginfmt"]',
                'input[type="email"]',
                'input[autocomplete="username"]',
                'input[id*="user"]',
                'input[id*="email"]',
                'input[id*="login"]',
              ]),
              passwordInput: firstVisible([
                'input[name="password"]',
                'input[name="passwd"]',
                'input[type="password"]',
                'input[autocomplete="current-password"]',
                'input[id*="pass"]',
              ]),
            };
          };

          const runAutoLoginStep = () => {
            const fields = loginFields();
            const usernameInput = fields.usernameInput;
            const passwordInput = fields.passwordInput;
            if (!usernameInput && !passwordInput) {
              clearAttempts();
              return 'no-login-form';
            }

            if (!USERNAME || !PASSWORD) {
              return 'missing-saved-credentials';
            }

            if (getAttempts() >= MAX_AUTO_LOGIN_ACTIONS) {
              return 'max-attempts-reached';
            }

            let changed = false;
            if (usernameInput) {
              changed = syncFieldValue(usernameInput, USERNAME, passwordInput ? 'username-password' : 'username-only') || changed;
            }
            if (passwordInput) {
              changed = syncFieldValue(passwordInput, PASSWORD, 'password-only') || changed;
            }
            if (changed) {
              return passwordInput ? 'filled-login-form' : 'filled-username-form';
            }

            if (
              fieldRecentlyFilled('username-only')
              || fieldRecentlyFilled('username-password')
              || fieldRecentlyFilled('password-only')
            ) {
              return 'awaiting-field-settle';
            }

            const form =
              (passwordInput && passwordInput.form)
              || (usernameInput && usernameInput.form)
              || document.querySelector('form');

            if (passwordInput) {
              const submitButton = findActionButton(SUBMIT_LABELS) || findActionButton(NEXT_LABELS);
              if (submitButton && canPerformAction('password-button')) {
                bumpAttempts();
                clickElement(submitButton);
                return 'clicked-login-button';
              }
              if (form && canPerformAction('password-form')) {
                bumpAttempts();
                submitForm(form, submitButton);
                return 'submitted-login-form';
              }
              return 'filled-login-form';
            }

            const nextButton = findActionButton(NEXT_LABELS) || findActionButton(SUBMIT_LABELS);
            if (nextButton && canPerformAction('username-button')) {
              bumpAttempts();
              clickElement(nextButton);
              return 'clicked-next-button';
            }
            if (form && canPerformAction('username-form')) {
              bumpAttempts();
              submitForm(form, nextButton);
              return 'submitted-username-form';
            }

            return 'filled-username-form';
          };

          const scheduleAutoLogin = (delay = 80) => {
            if (!USERNAME || !PASSWORD) {
              return;
            }
            window.clearTimeout(window.__klicStreetSmartAutoLoginHandle || 0);
            window.__klicStreetSmartAutoLoginHandle = window.setTimeout(() => {
              try {
                window.__klicStreetSmartLastLoginResult = runAutoLoginStep();
              } catch (_error) {
              }
            }, delay);
          };

          if (!window.__klicStreetSmartAutoLoginObserverAdded) {
            window.__klicStreetSmartAutoLoginObserverAdded = true;
            const observerTarget = document.documentElement || document.body;
            if (observerTarget) {
              const observer = new MutationObserver(() => {
                scheduleAutoLogin(90);
              });
              observer.observe(observerTarget, {
                childList: true,
                subtree: true,
                attributes: true,
                attributeFilter: ['class', 'style', 'hidden', 'aria-hidden', 'type', 'value'],
              });
            }
            document.addEventListener('input', () => scheduleAutoLogin(160), true);
            document.addEventListener('change', () => scheduleAutoLogin(160), true);
            window.addEventListener('focus', () => scheduleAutoLogin(60), true);
            window.addEventListener('pageshow', () => scheduleAutoLogin(60), true);
            window.__klicStreetSmartAutoLoginTimer = window.setInterval(() => {
              scheduleAutoLogin(0);
            }, 1200);
          }

          const initialResult = runAutoLoginStep();
          scheduleAutoLogin(320);
          return initialResult;
        })()
        """
